const openSql = `select v.visited_on, c.name as customer, s.name as fitter,
       v.area_m2, q.total, coalesce(q.state, 'no quote') as state,
       current_date - v.visited_on as days_since
from site_visits v
join customers c on c.id = v.customer_id
join staff s on s.id = v.fitter_id
left join quotes q on q.site_visit_id = v.id
where v.visited_on >= :since
  and (q.state is null or q.state <> 'accepted')
order by q.total desc nulls last;`;
