const VATR = 0.155;
const bRooms = [["Lounge", 5.2, 4.1], ["Passage", 6.0, 1.1]];
const bArea = bRooms.reduce((n, [, l, w]) => n + l * w, 0), bRun = 31.6, bDoors = 3;
const bUp = (q, p) => Math.ceil(q / p - 1e-9);
const QL2 = [["Laminate planks, oak", bArea, 1.1, 2.22, "packs", 38], ["Underlay", bArea, 1, 15, "rolls", 24], ["Moisture barrier", bArea, 1, 20, "rolls", 18], ["Skirting, 2.4 m lengths", bRun, 1.05, 2.4, "lengths", 6.5], ["Door bars", bDoors, 1, 1, "bars", 9], ["Fitting", bArea, 1, 0, "m²", 6]].map(([n, fig, w, pack, unit, price]) => { const qty = pack ? bUp(fig * w, pack) : Math.round(fig * w * 100) / 100; return { n, qty, unit, price, amt: Math.round(qty * price * 100) / 100 }; });
const qSub = Math.round(QL2.reduce((n, l) => n + l.amt, 0) * 100) / 100, qVat = Math.round(qSub * VATR * 100) / 100, qTot = Math.round((qSub + qVat) * 100) / 100;
