// documents: one A4 designer for quotes and invoices
const a4 = (kind, ref, to, addr, dates, lines, sums, extra, selKey) => `<div class="a4">
  <div class="a4-top"><div><div class="a4-brand">Floorcode</div><div>12 Coventry Road, Workington, Harare</div><div class="mono">VAT 220093114</div></div><div class="a4-t"><h2>${kind}</h2><div class="mono">${ref}</div></div></div>
  <div class="a4-cols"><div><div class="k">For</div><div class="v">${to}</div><div>${addr}</div></div><div style="text-align:right">${dates.map(([k, v]) => `<div class="k">${k}</div><div class="v">${v}</div>`).join("")}</div></div>
  <div class="${selKey === "lines" ? "selbox" : ""}">${selKey === "lines" ? `<span class="seltag">${ic("table-2-fill")}Lines</span>` : ""}<table class="a4-l"><thead><tr><th>Item</th><th class="r">Qty</th><th>Unit</th><th class="r">Price</th><th class="r">Amount</th></tr></thead><tbody>${lines.map(([n, q, u, p, a]) => `<tr><td>${n}</td><td class="r mono">${q}</td><td>${u}</td><td class="r mono">${p}</td><td class="r mono">${a}</td></tr>`).join("")}</tbody></table></div>
  <div class="a4-sums">${sums.map(([k, v, t]) => `<div${t ? ' class="t"' : ""}><span>${k}</span><span class="mono">${v}</span></div>`).join("")}</div>
  ${extra}</div>`;
const a4Css = `
.a4{position:relative;width:640px;min-height:860px;padding:48px 52px;background:var(--color-surface);box-shadow:var(--shadow-ring),0 16px 40px -20px rgba(11,12,20,.3);display:flex;flex-direction:column;gap:var(--space-24);font-size:var(--text-12);color:var(--color-ink-2)}
.a4-top{display:flex;justify-content:space-between}.a4-brand{font-size:var(--text-20);font-weight:600;color:var(--color-ink);margin-bottom:var(--space-4)}.a4-t{text-align:right}.a4-t h2{font-size:var(--text-20);font-weight:600;color:var(--color-ink)}
.a4-cols{display:flex;justify-content:space-between}.k{font-size:var(--text-12);color:var(--color-muted)}.v{font-size:var(--text-14);font-weight:500;color:var(--color-ink)}
.a4-l{width:100%;border-collapse:collapse}.a4-l th{height:32px;text-align:left;font-weight:500;color:var(--color-muted);box-shadow:inset 0 -1px 0 var(--color-ink)}.a4-l td{height:32px;box-shadow:inset 0 -1px 0 var(--color-line);color:var(--color-ink)}.a4-l .r{text-align:right}
.a4-sums{align-self:flex-end;width:260px;display:flex;flex-direction:column}.a4-sums>div{display:flex;justify-content:space-between;height:28px;align-items:center}.a4-sums .t{font-size:var(--text-14);font-weight:600;color:var(--color-ink);box-shadow:inset 0 1px 0 var(--color-ink)}
.a4-x{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-24);margin-top:auto;padding-top:var(--space-16);box-shadow:inset 0 1px 0 var(--color-line)}.a4-x b{display:block;font-size:var(--text-12);font-weight:600;color:var(--color-ink);margin-bottom:var(--space-4)}
.fisc{display:flex;gap:var(--space-12);align-items:center}.qr{width:72px;height:72px;flex:none;background-image:repeating-linear-gradient(0deg,var(--color-ink) 0 4px,transparent 4px 8px),repeating-linear-gradient(90deg,var(--color-ink) 0 4px,transparent 4px 8px);background-blend-mode:multiply;opacity:.85;border-radius:2px}`;
const docOutline = (sel) => oGroup("Page", `${oItem("building-2-fill", "Letterhead", { q: "Branding" })}${oItem("user-3-fill", "Customer and dates")}`) + oGroup("Body", `${oItem("table-2-fill", "Lines", { on: sel === "lines", q: "quote_lines" })}${oItem("hashtag-fill", "Totals", { q: "worked out" })}`) + oGroup("Foot", `${oItem("paper-fill", "Terms")}${sel === "fiscal" ? oItem("safe-box-fill", "Fiscal block", { on: 1, q: "ZIMRA" }) + oItem("qrcode-fill", "Pay with EcoCash") : oItem("edit-2-fill", "Signature")}`);

